"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Icon } from "@/components/ui/icon-provider"
import { handleTabListKeyDown, useRovingTabStop } from "@/lib/roving-tabs"
import { Badge } from "@/components/ui/badge"
import { KbdHint } from "@/components/ui/kbd"
import { ItemCardCover, ItemCardFile, type ItemCardFileProps } from "@/components/wunderui/item-card"
import { TimelineEntry, type TimelineEntryProps } from "@/components/wunderui/timeline"

/* ------------------------------------------------------------------ */
/* Keyboard Hint, Command Item Row, Search Result — deprecated aliases */
/* of KbdHint (Kbd), CommandRow (Command), SearchResultRow (Search     */
/* Result Card)                                                         */
/* ------------------------------------------------------------------ */

/** @deprecated Use `KbdHint`. */
const KeyboardHint = KbdHint

/* ------------------------------------------------------------------ */
/* Checklist Task — onboarding checklist row                            */
/* Figma: Checklist Task (693:123)                                     */
/* ------------------------------------------------------------------ */

/**
 * One step of an onboarding checklist. Three states, as in the Figma set:
 * `done` (green tick, muted label), the `current` step (tinted row, a line of
 * explanation and its own call to action) and everything still to do (empty
 * circle and a chevron).
 *
 * The row is a toggle: `onClick` fires for done and open steps alike, so a
 * step can be ticked and unticked again. On the current step the circle is its
 * own button, because the row already carries the `action`.
 */
function ChecklistTask({
  done,
  current,
  children,
  meta,
  action,
  onClick,
  className,
}: {
  done?: boolean
  /** The step to do next — tinted, with room for `meta` and an `action`. */
  current?: boolean
  children: React.ReactNode
  meta?: React.ReactNode
  /** A button shown on the current step, e.g. "Start". */
  action?: React.ReactNode
  /** Toggle the step. */
  onClick?: () => void
  className?: string
}) {
  const circle = (
    <span
      className={cn(
        "grid size-[22px] shrink-0 place-items-center rounded-full transition-colors duration-fast ease-move",
        done ? "bg-success text-success-foreground" : cn("border-[1.5px] bg-card", current ? "border-tint-text-indigo" : "border-muted-foreground group-hover/task:border-primary")
      )}
    >
      {done && <Icon name="check" className="size-3.5 animate-in zoom-in-50 duration-fast" strokeWidth={1.5} />}
    </span>
  )

  const label = (
    <span className="flex min-w-0 flex-1 flex-col">
      <span
        className={cn(
          "text-sm font-medium transition-colors duration-fast ease-move",
          done ? "text-text-tertiary" : current ? "text-tint-text-indigo" : "text-foreground"
        )}
      >
        {children}
      </span>
      {meta && (
        <span className={cn("text-xs", current ? "text-tint-text-indigo" : "text-text-tertiary")}>{meta}</span>
      )}
    </span>
  )

  const classes = cn(
    "group/task flex w-full items-center gap-3 rounded-md px-3 py-2 text-start transition-colors duration-fast ease-move outline-none focus-ring",
    current ? "bg-tint-indigo py-3" : "hover:bg-muted/50",
    className
  )

  // The current step carries its own button, so the row itself must not be one.
  if (current) {
    return (
      <div data-slot="checklist-task" data-current className={classes}>
        <button type="button" role="checkbox" aria-checked={Boolean(done)} aria-label="Mark as done" onClick={onClick} className="rounded-full outline-none focus-ring">
          {circle}
        </button>
        {label}
        {action}
      </div>
    )
  }

  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={Boolean(done)}
      data-slot="checklist-task"
      data-done={done || undefined}
      onClick={onClick}
      className={cn(classes, "outline-none focus-ring")}
    >
      {circle}
      {label}
      {!done && <Icon name="chevronRight" className="size-4 text-text-tertiary" strokeWidth={1.5} />}
    </button>
  )
}

/** @deprecated Use `ItemCardCover` with the same props. */
const ProjectCard = ItemCardCover

type FileCardProps = ItemCardFileProps

/** @deprecated Use `ItemCardFile` with the same props. */
const FileCard = ItemCardFile

/* ------------------------------------------------------------------ */
/* Tab Item — underline tab with optional count                        */
/* Figma: Tab Item (693:167)                                           */
/* ------------------------------------------------------------------ */

type TabItemProps = Omit<React.ComponentProps<"button">, "children" | "onClick"> & {
  active?: boolean
  count?: React.ReactNode
  children: React.ReactNode
  onClick?: () => void
}

/**
 * @deprecated Use `Tabs` (`variant="line"`) with `TabsTrigger count`.
 *
 * Pass `id` and `aria-controls` (and `aria-labelledby` on your panel) to tie the tab to its panel.
 */
function TabItem({ active, count, children, onClick, className, ...props }: TabItemProps) {
  return (
    <button
      type="button"
      role="tab"
      aria-selected={!!active}
      data-slot="tab-item"
      onClick={onClick}
      {...props}
      className={cn("group/tab-item -mb-px flex shrink-0 flex-col gap-2 rounded-sm pt-2 text-sm font-medium whitespace-nowrap transition-colors duration-fast ease-entrance outline-none focus-ring focus-visible:-outline-offset-2! disabled:pointer-events-none disabled:opacity-40", active ? "text-text-link" : "text-text-secondary hover:text-foreground", className)}
    >
      <span className="flex items-center gap-2">
        {children}
        {active && count !== undefined && (
          <Badge color="indigo" badgeStyle="light" shape="pill">
            {count}
          </Badge>
        )}
      </span>
      {/* The bar overlaps the 1 px line of the TabBar (-mb-px on the tab): the underline, active or on hover, sits exactly on the divider. */}
      <span className={cn("h-0.5 w-full rounded-full transition-colors duration-fast ease-entrance", active ? "bg-primary" : "bg-transparent group-hover/tab-item:bg-border-control")} />
    </button>
  )
}

/** @deprecated Use `Tabs` with `TabsList variant="line"`. Tabs pattern: one tab stop (the active tab); ←/→ move and activate, Home/End jump, both wrap. */
function TabBar({ children, className, "aria-label": ariaLabel }: { children: React.ReactNode; className?: string; "aria-label"?: string }) {
  const ref = React.useRef<HTMLDivElement>(null)
  useRovingTabStop(ref)
  return (
    <div ref={ref} role="tablist" aria-label={ariaLabel} data-slot="tab-bar" onKeyDown={handleTabListKeyDown} className={cn("flex gap-6 overflow-x-auto border-b border-border [scrollbar-width:none]", className)}>
      {children}
    </div>
  )
}

/* ------------------------------------------------------------------ */
/* Timeline Event — moved to TimelineEntry (wunderui/timeline.tsx)     */
/* ------------------------------------------------------------------ */

/** @deprecated Use `TimelineEntry` from the Timeline component. Same props, same look. */
const TimelineEvent = TimelineEntry
type TimelineEventProps = TimelineEntryProps

export { KeyboardHint, ChecklistTask, ProjectCard, FileCard, TabItem, TabBar, TimelineEvent }
export type { TabItemProps, FileCardProps, TimelineEventProps }

import type { ReactNode } from "react"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage, type AvatarColor } from "@/components/ui/avatar"
import { Badge, type BadgeColor } from "@/components/ui/badge"
import { readableOn, readableOnCss } from "@/lib/readable-on"

type TimelineItem = {
  id: string
  title: ReactNode
  description?: ReactNode
  timestamp?: string
  icon?: ReactNode
  /** A person instead of the dot, for activity feeds: an Avatar, for example. */
  avatar?: ReactNode
  /** Fill of the dot. The glyph inside switches between white and a dark colour so it stays readable (WCAG 1.4.11). */
  color?: string
}

/** Dot fill plus a glyph colour with enough contrast on it. */
function dotStyle(color: string | undefined) {
  const tone = color ? readableOn(color) : "light"
  return {
    className: tone === "dark" ? "text-neutral-dark-content" : "text-white",
    // A fill that is not a literal colour (var(), color-mix) is resolved in CSS.
    style: {
      backgroundColor: color ?? "var(--primary)",
      ...(tone === null && color ? { color: readableOnCss(color) } : null),
    },
  }
}

function Timeline({
  items,
  orientation = "vertical",
  compact = false,
  className,
}: {
  items: TimelineItem[]
  /** "vertical" stacks the entries, "horizontal" lays them out in a row with the time above each dot. */
  orientation?: "vertical" | "horizontal"
  /** Smaller dots and text, for milestones and long lists. */
  compact?: boolean
  className?: string
}) {
  const dot = (item: TimelineItem) =>
    item.avatar ?? (
      <span
        data-slot="timeline-dot"
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full",
          compact ? "size-4 [&_svg]:size-2.5" : "size-6",
          dotStyle(item.color).className
        )}
        style={dotStyle(item.color).style}
      >
        {item.icon ?? <span className={cn("rounded-full bg-current", compact ? "size-1" : "size-1.5")} />}
      </span>
    )

  if (orientation === "horizontal") {
    return (
      <div data-slot="timeline" data-orientation="horizontal" className={cn("flex", className)}>
        {items.map((item, i) => (
          <div key={item.id} className="flex min-w-0 flex-1 flex-col gap-2">
            {item.timestamp && <span className="text-xs text-text-tertiary">{item.timestamp}</span>}
            <div className="flex items-center">
              {dot(item)}
              {i !== items.length - 1 && <span className="mx-2 h-px flex-1 bg-border" />}
            </div>
            <div className="flex flex-col gap-0.5 pr-3">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.description && <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>}
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div data-slot="timeline" className={cn("flex flex-col", className)}>
      {items.map((item, i) => (
        <div key={item.id} className="flex gap-3">
          <div className="flex flex-col items-center">
            {dot(item)}
            {i !== items.length - 1 && <span className="my-1 w-px flex-1 bg-border" />}
          </div>
          <div className={cn("flex flex-col gap-0.5", i !== items.length - 1 && (compact ? "pb-4" : "pb-6"))}>
            <div className="flex items-center gap-2">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.timestamp && (
                <span className="text-xs text-text-tertiary">{item.timestamp}</span>
              )}
            </div>
            {item.description && (
              <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

/** One entry of an activity feed or history: an avatar or a status dot, a title, a time, an object chip, a badge, a meta line, content below and a line to the next entry. Stack entries in a column; pass `last` on the final one. */
type TimelineEntryProps = {
  /** Actor avatar (Type=event). */
  avatar?: { src?: string; initials?: string; color?: AvatarColor }
  /** Status dot (Type=step): tone + icon. */
  status?: { tone?: "success" | "primary" | "warning" | "muted"; icon?: ReactNode }
  title: ReactNode
  time?: ReactNode
  /** Small object chip under the title (Type=event) — e.g. project name. */
  object?: { icon?: ReactNode; label: ReactNode }
  /** Trailing badge/label on the title row (Type=step). */
  badge?: ReactNode
  badgeColor?: BadgeColor
  meta?: ReactNode
  /** Extra content below the title (comment excerpt, reactions, attachments …). */
  children?: ReactNode
  /** The last entry of the list: no connector line below it. */
  last?: boolean
  className?: string
}

const ENTRY_TONE = {
  success: "bg-success text-success-foreground",
  primary: "bg-primary text-primary-foreground",
  warning: "bg-brand-quaternary text-foreground",
  muted: "bg-muted text-text-secondary",
}

function TimelineEntry({ avatar, status, title, time, object, badge, badgeColor = "grey", meta, children, last, className }: TimelineEntryProps) {
  const lineColor = status?.tone === "success" ? "bg-success" : "bg-border"
  return (
    <div data-slot="timeline-entry" className={cn("flex gap-4", className)}>
      <div className="flex w-10 shrink-0 flex-col items-center">
        {avatar ? (
          <Avatar size="lg" color={avatar.src ? undefined : avatar.color}>
            {avatar.src && <AvatarImage src={avatar.src} alt="" />}
            <AvatarFallback>{avatar.initials}</AvatarFallback>
          </Avatar>
        ) : (
          <span className={cn("grid size-8 place-items-center rounded-full [&_svg]:size-3.5", ENTRY_TONE[status?.tone ?? "muted"])}>
            {status?.icon ?? <Icon name="check" strokeWidth={1.5} />}
          </span>
        )}
        {!last && <span className={cn("mt-1 w-0.5 flex-1", lineColor)} />}
      </div>
      <div className={cn("flex min-w-0 flex-1 flex-col gap-1", !last && "pb-6")}>
        <div className="flex items-start justify-between gap-2">
          <p className="text-sm text-text-secondary [&_strong]:font-medium [&_strong]:text-foreground">{title}</p>
          {time && <span className="shrink-0 text-xs text-text-tertiary">{time}</span>}
          {badge && (
            <Badge color={badgeColor} badgeStyle="light" shape="pill" className="shrink-0">
              {badge}
            </Badge>
          )}
        </div>
        {object && (
          <span className="inline-flex w-fit items-center gap-1 rounded-md bg-muted px-2 py-0.5 text-[11px] text-text-secondary [&_svg]:size-3">
            {object.icon ?? <Icon name="folder" strokeWidth={1.5} />}
            {object.label}
          </span>
        )}
        {meta && <p className="text-xs text-text-tertiary">{meta}</p>}
        {children}
      </div>
    </div>
  )
}

export { Timeline, TimelineEntry }
export type { TimelineItem, TimelineEntryProps }

/**
 * Picks the glyph colour for text or an icon drawn on an arbitrary fill.
 *
 * `readableOn("#FACA4A")` returns "dark" (white would be 1.6:1, the dark
 * content colour 9.8:1). A fill the function cannot parse (var(), named
 * colours, color-mix()) returns null; the caller then lets CSS decide.
 */

const DARK_CONTENT = "#25272A" // --neutral-dark-content

function channel(value: number) {
  const v = value / 255
  return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4
}

function luminance([r, g, b]: [number, number, number]) {
  return 0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

function parseColor(input: string): [number, number, number] | null {
  const value = input.trim().toLowerCase()
  const hex = /^#([0-9a-f]{3,8})$/.exec(value)
  if (hex) {
    let h = hex[1]
    if (h.length === 3 || h.length === 4) h = [...h].map((c) => c + c).join("")
    if (h.length !== 6 && h.length !== 8) return null
    return [parseInt(h.slice(0, 2), 16), parseInt(h.slice(2, 4), 16), parseInt(h.slice(4, 6), 16)]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/.exec(value)
  if (rgb) return [Number(rgb[1]), Number(rgb[2]), Number(rgb[3])]
  return null
}

/** "light" = white glyph, "dark" = dark glyph, whichever has the higher WCAG contrast; null = unknown fill. */
export function readableOn(fill: string): "light" | "dark" | null {
  const rgb = parseColor(fill)
  if (!rgb) return null
  const y = luminance(rgb)
  const white = 1.05 / (y + 0.05)
  const dark = (y + 0.05) / (luminance(parseColor(DARK_CONTENT)!) + 0.05)
  return white >= dark ? "light" : "dark"
}

/**
 * CSS-only counterpart for fills that are not literal colours (relative colour
 * syntax: white on dark fills, a near-black on light ones, switching at the
 * point where both have the same contrast).
 */
export function readableOnCss(fill: string): string {
  return `oklch(from ${fill} clamp(0.25, (0.6 - l) * 1000, 1) 0 0)`
}

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon, type IconName } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

// Hex per color - the same hue set as the Figma "Badge" component (600 step
// of each Primitives scale). Kept as plain hex (not CSS vars) so color-mix()
// below can compute the light/opacity variants at runtime.
const BADGE_COLORS = {
  blue: "#12AFF0",
  green: "#1AD598",
  red: "#F47690",
  yellow: "#FACA4A",
  purple: "#A584F3",
  indigo: "#555CF3",
  pink: "#FE6BBA",
  orange: "#F3654A",
  alternative: "#6E6D86",
  grey: "#A2A3A3",
  black: "#000000",
  white: "#FFFFFF",
} as const

type BadgeColor = keyof typeof BADGE_COLORS

const badgeVariants = cva(
  cn(
    "group/badge inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border border-transparent font-semibold whitespace-nowrap transition duration-fast ease-entrance [&>svg]:pointer-events-none",
    // Rendered as a button or link, a badge is a chip: it answers the pointer
    // and the keyboard like any other control.
    //
    // The hover cue is a ring in the label's own colour, not a brightness
    // filter. brightness() moves fill and label together, and because the label
    // polarity differs per colour — a deep hue on a bright fill in light mode,
    // white on indigo and alternative in dark mode — no single factor is safe in
    // both directions: brightness-95/125 measured 3.40:1 on dark alternative,
    // 3.81:1 on dark indigo and 4.44:1 on light orange, and the factors that
    // clear AA everywhere (98%/106%) are too small to see. A ring changes
    // nothing about the label's backdrop, so contrast is unaffected whatever the
    // colour. See /scripts/contrast-audit.mjs, which reads this hover treatment
    // out of this file.
    "[&:is(button,a)]:cursor-pointer [&:is(button,a)]:outline-none [&:is(button,a)]:hover:ring-2 [&:is(button,a)]:hover:ring-current/30 [&:is(button,a)]:active:scale-95 motion-reduce:[&:is(button,a)]:active:scale-100 [&:is(button,a)]:focus-ring"
  ),
  {
    variants: {
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        sm: "h-5 gap-1 px-2 text-xs [&>svg]:size-3!",
        md: "h-6 gap-1.5 px-2.5 text-sm [&>svg]:size-3.5!",
      },
    },
    defaultVariants: {
      shape: "rounded",
      size: "sm",
    },
  }
)

type BadgeStyle = "plain" | "light" | "light_border" | "border_color" | "border_grey" | "ghost"

// Hues that have a Figma tint pair (`tint/<hue>` surface + `tint-text/<hue>`
// text, both mode-aware). Grey, black and white have none and fall back to
// color-mix() below.
const TINTED: readonly BadgeColor[] = ["blue", "green", "red", "yellow", "purple", "indigo", "pink", "orange", "alternative"]

// Text on a solid fill: white on every hue (owner decision Nov 17 2026: white text on solid colour, never black). The one exception is the white badge, whose fill is white itself, so it keeps black text.
const SOLID_TEXT_DARK: readonly BadgeColor[] = ["white"]

// The two achromatic badges are spelled out in Figma rather than derived: a
// black badge pales to the grey scale, a white one to the surface grey — a
// color-mix of #000 or #FFF lands somewhere else entirely.
// `text` sits on the badge's own fill; `ink` sits on the card or on nothing at
// all (outline, ghost), so it has to follow the mode — pure black there would
// vanish into a dark card.
const ACHROMATIC: Partial<Record<BadgeColor, { bg: string; text: string; ink: string; border: string }>> = {
  black: { bg: "var(--dark-200)", text: "#000000", ink: "var(--foreground)", border: "var(--dark-300)" },
  white: { bg: "var(--muted)", text: "var(--foreground)", ink: "var(--foreground)", border: "var(--border-control)" },
  // Grey has no tint pair; its 600 hue (#A2A3A3) is a fill colour, too pale
  // for a label on white. Text takes the tertiary text token instead (AA in
  // both modes), the surface keeps the grey hue.
  grey: {
    // 10 % (not 16 %) keeps the tertiary text at 4.7:1 on the surface — 16 % measured 4.46:1
    bg: "color-mix(in srgb, #A2A3A3 10%, var(--card))",
    text: "var(--text-tertiary)",
    ink: "var(--text-tertiary)",
    border: "var(--border-control)",
  },
}

// Figma Badge / Plain: the label sits on the page, not on a tint, so it takes the semantic text token
// (link, success, error) where one exists and the hue's tint-text everywhere else.
const GHOST_TEXT: Partial<Record<BadgeColor, string>> = {
  indigo: "var(--text-link)",
  green: "var(--text-success)",
  red: "var(--text-error)",
}

function styleToCss(color: BadgeColor, style: BadgeStyle) {
  const hex = BADGE_COLORS[color]
  const tinted = TINTED.includes(color)
  const flat = ACHROMATIC[color]
  const tintBg = flat ? flat.bg : tinted ? `var(--tint-${color})` : `color-mix(in srgb, ${hex} 12%, var(--card))`
  const tintText = flat ? flat.text : tinted ? `var(--tint-text-${color})` : hex === "#FFFFFF" ? "#000000" : hex
  const inkText = flat ? flat.ink : tintText
  const tintBorder = flat
    ? flat.border
    : tinted
      ? `color-mix(in srgb, var(--tint-text-${color}) 40%, var(--card))`
      : `color-mix(in srgb, ${hex} 40%, var(--card))`
  // Figma Badge / Outline: the rim is the tint-text token of the hue itself (a variable, not a blend).
  const outlineBorder = flat ? flat.border : tinted ? `var(--tint-text-${color})` : tintBorder
  switch (style) {
    case "plain":
      return {
        background: hex,
        borderColor: hex,
        color: SOLID_TEXT_DARK.includes(color) ? "#000000" : "#FFFFFF",
      }
    case "light":
      return {
        background: tintBg,
        borderColor: "transparent",
        color: tintText,
      }
    case "light_border":
      return {
        background: tintBg,
        borderColor: outlineBorder,
        color: tintText,
      }
    case "border_color":
      return {
        background: "var(--card)",
        borderColor: tintBorder,
        color: inkText,
      }
    case "border_grey":
      return {
        background: "var(--card)",
        borderColor: "var(--border)",
        color: inkText,
      }
    case "ghost":
      return {
        background: "transparent",
        borderColor: "transparent",
        color: GHOST_TEXT[color] ?? inkText,
      }
  }
}

function Badge({
  className,
  shape,
  size = "sm",
  color = "blue",
  badgeStyle = "plain",
  style,
  render,
  dot,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    color?: BadgeColor
    badgeStyle?: BadgeStyle
    dot?: boolean
    onRemove?: () => void
    removeLabel?: string
  }) {
  // Don't render the remove button when the badge is a button/link (`render`),
  // as that would nest interactive elements.
  const removeButton = onRemove && render === undefined ? (
    <button
      type="button"
      data-slot="badge-remove"
      aria-label={removeLabel}
      onClick={onRemove}
      className="relative -me-1 ms-0.5 inline-flex size-4 shrink-0 cursor-pointer after:absolute after:-inset-1 after:content-['']  items-center justify-center rounded-full outline-none transition duration-fast ease-entrance hover:bg-current/15 active:scale-90 motion-reduce:active:scale-100 focus-ring"
    >
      <Icon name="close" aria-hidden="true" className="size-3" />
    </button>
  ) : null

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(badgeVariants({ shape, size }), className),
        style: { ...styleToCss(color, badgeStyle), ...style },
        children: (
          <>
            {dot && (
              <span
                data-slot="badge-dot"
                aria-hidden="true"
                className="size-1.5 shrink-0 rounded-full bg-current"
              />
            )}
            {opticalCenter(children)}
            {removeButton}
          </>
        ),
      },
      props
    ),
    render,
    state: {
      slot: "badge",
      color,
      badgeStyle,
      size,
      ...(dot ? { dot: true } : {}),
    },
  })
}

type BadgeCounterTone = "neutral" | "brand" | "danger"

const BADGE_COUNTER_TONE_CLASSES: Record<BadgeCounterTone, string> = {
  neutral: "bg-bg-subtle text-foreground data-[zero]:text-text-tertiary",
  brand: "bg-primary text-primary-foreground",
  danger: "bg-destructive text-destructive-foreground",
}

const BADGE_COUNTER_KIND_CLASSES: Record<"inline" | "overlay", string> = {
  inline: "h-5 min-w-5 px-1.5 text-xs font-medium",
  overlay: "absolute top-0 right-0 z-10 h-4 min-w-4 translate-x-1/2 -translate-y-1/2 px-1 text-[11px] font-medium ring-2 ring-card",
}

function BadgeCounter({
  count,
  max = 99,
  tone = "neutral",
  overlay = false,
  hideZero,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  count: number
  max?: number
  tone?: BadgeCounterTone
  overlay?: boolean
  hideZero?: boolean
}) {
  const resolvedHideZero = hideZero ?? overlay
  const shown = Math.max(0, Math.trunc(count))
  if (shown <= 0 && resolvedHideZero) return null
  const text = shown > max ? `${max}+` : String(shown)

  return (
    <span
      data-slot="badge-counter"
      data-tone={tone}
      data-kind={overlay ? "overlay" : "inline"}
      data-zero={shown === 0 ? "" : undefined}
      className={cn(
        "inline-flex items-center justify-center rounded-full tabular-nums leading-none whitespace-nowrap select-none",
        BADGE_COUNTER_KIND_CLASSES[overlay ? "overlay" : "inline"],
        BADGE_COUNTER_TONE_CLASSES[tone],
        className
      )}
      {...props}
    >
      <span className="optical-center">{text}</span>
    </span>
  )
}

