  ...props
}: ButtonPrimitive.Props &
  VariantProps<typeof iconButtonVariants> & {
    /**
     * Shows a spinner in place of the icon, in the same square, and ignores presses.
     * The button stays focusable and keeps its colour (it is not disabled).
     */
    pending?: boolean
    /**
     * Async feedback in the same square: pending shows a spinner, success a check, error a retry icon.
     * The size never changes. The accessible name is yours: change the aria-label with the phase
     * (for example Copy link, Copying, Copied, Retry copying).
     */
    phase?: IconButtonPhase
    /**
     * Marks a trigger whose menu or panel is open: sets aria-expanded and the pressed surface
     * (bg-bg-subtle) on the quiet variants. Leave it undefined when the button does not control a popup.
     */
    expanded?: boolean
  }) {
  const status: IconButtonPhase = phase ?? (pending ? "pending" : "idle")
  const isIdle = status === "idle"

  const resolvedVariant = variant ?? "primary"
  const effectiveVariant =
    status === "error" && ["primary", "brand", "gradient"].includes(resolvedVariant)
      ? "destructive"
      : variant

  const quiet = ["plain", "ghost", "outline"].includes(resolvedVariant)

  let statusIcon: React.ReactNode = null
  if (status === "pending") {
    statusIcon = (
      <Icon name="spinner" aria-hidden className="animate-spin motion-reduce:animate-none" />
    )
  } else if (status === "success") {
    statusIcon = (
      <Icon name="check" aria-hidden strokeWidth={2} className={quiet ? "text-text-success" : undefined} />
    )
  } else if (status === "error") {
    statusIcon = (
      <Icon name="retry" aria-hidden strokeWidth={2} className={quiet ? "text-text-error" : undefined} />
    )
  }

  const handleClick: NonNullable<ButtonPrimitive.Props["onClick"]> = (event) => {
    if (status === "pending") {
      event.preventDefault()
      return
    }
    onClick?.(event)
  }

  return (
    <ButtonPrimitive
      data-slot="icon-button"
      className={cn(iconButtonVariants({ variant: isIdle ? variant : effectiveVariant, shape, size, className }))}
      aria-expanded={expanded}
      data-expanded={expanded ? "" : undefined}
      data-phase={isIdle ? undefined : status}
      aria-busy={isIdle ? undefined : status === "pending" ? true : undefined}
      data-pending={isIdle ? undefined : status === "pending" ? "" : undefined}
      onClick={isIdle ? onClick : handleClick}
      {...props}
    >
      {isIdle ? children : statusIcon}
    </ButtonPrimitive>
  )
}

export { IconButton, iconButtonVariants }
export type { IconButtonPhase }

"use client"

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { cn } from "@/lib/utils"
import { Icon } from "@/components/ui/icon-provider"
import * as React from "react"

/**
 * Base UI renders a hidden native <input> next to the visible control and gives it no name.
 * It is aria-hidden, but page checkers still list it as an unlabelled form control, so the
 * control's aria-label / aria-labelledby is mirrored onto it.
 */
function useNamedHiddenInput(inputRef: React.Ref<HTMLInputElement> | undefined, label?: string, labelledBy?: string) {
  return React.useCallback(
    (node: HTMLInputElement | null) => {
      if (node) {
        if (label) node.setAttribute("aria-label", label)
        else node.removeAttribute("aria-label")
        if (labelledBy) node.setAttribute("aria-labelledby", labelledBy)
        else node.removeAttribute("aria-labelledby")
      }
      if (typeof inputRef === "function") inputRef(node)
      else if (inputRef) (inputRef as React.RefObject<HTMLInputElement | null>).current = node
    },
    [inputRef, label, labelledBy]
  )
}

// Figma Appearance=Neutral: the filled box is the inverse surface (black in light, white in dark)
// with an inverse-coloured check instead of the brand fill. Hover and disabled stay as they are; an invalid box keeps its red rim.
const NEUTRAL_CHECKED =
  "data-checked:border-inverse data-checked:bg-inverse data-checked:text-text-inverse dark:data-checked:bg-inverse data-indeterminate:border-inverse data-indeterminate:bg-inverse data-indeterminate:text-text-inverse group-has-[:focus-visible]/field-label:data-checked:border-inverse"

// Figma Appearance=Brand: the filled box darkens on hover (brand-700) and pressed (brand-800), the same
// fixed tokens as the primary button, so the white mark keeps its contrast in both themes (7.0:1, 10.0:1).
// The border follows the fill unless the box is invalid (the red rim stays).
const BRAND_STATES =
  "hover:data-checked:bg-(--brand-700) hover:data-indeterminate:bg-(--brand-700) active:data-checked:bg-(--brand-800) active:data-indeterminate:bg-(--brand-800) hover:data-checked:not-aria-invalid:border-(color:--brand-700) hover:data-indeterminate:not-aria-invalid:border-(color:--brand-700) active:data-checked:not-aria-invalid:border-(color:--brand-800) active:data-indeterminate:not-aria-invalid:border-(color:--brand-800)"

type CheckboxControlProps = CheckboxPrimitive.Root.Props & {
  /** `brand` fills the checked box with the brand colour; `neutral` fills it with the inverse (black/white) surface. */
  appearance?: "brand" | "neutral"
}

type CheckboxFieldProps = {
  /** Visible label to the right of the box. Joined to the box with `htmlFor`; a click on it toggles the box. */
  label?: React.ReactNode
  /** A second line under the label in the tertiary colour. */
  description?: React.ReactNode
  /** Error message under the row. Sets `aria-invalid` and `aria-describedby` on the box and turns its rim red. */
  error?: React.ReactNode
  /** Class names for the row (or, with `error`, for the wrapper around the row and the message). */
  wrapperClassName?: string
}

type CheckboxProps = CheckboxControlProps & CheckboxFieldProps

/** The props that turn the bare box into a field row. Presence of the prop counts, not its value, so a
 *  conditional `error={cond ? "…" : undefined}` never swaps the DOM (and drops the focus) when it flips. */
const FIELD_PROPS = ["label", "description", "error", "wrapperClassName"] as const

/**
 * Checkbox. Without any of the field props (`label`, `description`, `error`,
 * `wrapperClassName`) it renders the bare box. With one of them it renders the
 * row: the box and its label (and description) in one `<label>`, so the whole
 * row is the click target; `error` adds the message under the row.
 */
function Checkbox(props: CheckboxProps) {
  const autoId = React.useId()
  if (!FIELD_PROPS.some((key) => key in props)) return <CheckboxControl {...props} />

  const { label, description, error, wrapperClassName, id: idProp, className, ...rest } = props
  const id = idProp ?? autoId
  // The message sits outside the label so it is not read as part of the box's name.
  const withMessage = "error" in props
  const row = (
    <label
      htmlFor={id}
      data-slot={withMessage ? undefined : "checkbox-field"}
      className={cn("group/checkbox-field flex cursor-pointer items-start gap-2 has-[[data-disabled]]:cursor-not-allowed", !withMessage && wrapperClassName)}
    >
      <CheckboxControl
        id={id}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-error` : undefined}
        className={cn("mt-0.5", className)}
        {...rest}
      />
      <span className="flex flex-col gap-0.5">
        {label && (
          <span className="text-sm text-text-secondary group-has-[[data-disabled]]/checkbox-field:opacity-40 [&_a]:font-medium [&_a]:text-text-link [&_a]:hover:underline">{label}</span>
        )}
        {description && <span className="text-xs text-text-tertiary group-has-[[data-disabled]]/checkbox-field:opacity-40">{description}</span>}
      </span>
    </label>
  )
  if (!withMessage) return row
  return (
    <div data-slot="checkbox-field" className={cn("flex flex-col gap-1", wrapperClassName)}>
      {row}
      {error && (
        <p id={`${id}-error`} className="ps-6 text-xs text-text-error">
          {error}
        </p>
      )}
    </div>
  )
}

function CheckboxControl({
  className,
  inputRef,
  appearance = "brand",
  ...props
}: CheckboxControlProps) {
  const namedInputRef = useNamedHiddenInput(inputRef, props["aria-label"], props["aria-labelledby"])
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      data-appearance={appearance}
      inputRef={namedInputRef}
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[4px] border border-border-control bg-card transition-colors duration-fast ease-entrance outline-none hover:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary active:not-data-checked:not-data-indeterminate:not-aria-invalid:border-primary hover:not-data-checked:not-data-indeterminate:bg-bg-page active:not-data-checked:not-data-indeterminate:bg-bg-subtle after:absolute after:-inset-x-3 after:-inset-y-2 focus-ring data-disabled:cursor-not-allowed data-disabled:opacity-40 aria-invalid:border-error aria-invalid:focus-ring-error data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground data-indeterminate:border-primary data-indeterminate:bg-primary data-indeterminate:text-primary-foreground aria-invalid:data-checked:border-error aria-invalid:data-indeterminate:border-error",
        appearance === "brand" && BRAND_STATES,
        appearance === "neutral" && NEUTRAL_CHECKED,
        className
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        keepMounted
        data-slot="checkbox-indicator"
        className={cn(
          "grid place-content-center text-current opacity-0 transition-opacity ease-entrance duration-fast data-checked:opacity-100 data-indeterminate:opacity-100 [&>svg]:size-3.5 [&>svg:last-child]:hidden data-indeterminate:[&>svg:first-child]:hidden data-indeterminate:[&>svg:last-child]:block",
          // The box fills instantly (see Root's data-checked:bg-primary above);
          // the check stroke draws in after via stroke-dashoffset. 23 is
          // lucide's CheckIcon path length (getTotalLength()), rounded up by 1
          // so the draw never over/under-shoots. Uncheck reverses fast with no
          // draw — transitioning offset (not toggling display) is what lets a
          // mid-draw uncheck reverse cleanly instead of jumping. The offset is
          // negative because lucide's path starts at the top-right end: the
          // tick draws from its short stroke up to the long one, like by hand.
          "[&_svg_path]:[stroke-dasharray:23] [&_svg_path]:[stroke-dashoffset:-23] [&_svg_path]:transition-[stroke-dashoffset] [&_svg_path]:duration-fast [&_svg_path]:ease-entrance data-checked:[&_svg_path]:[stroke-dashoffset:0] data-indeterminate:[&_svg_path]:[stroke-dashoffset:0] data-checked:[&_svg_path]:duration-slow"
        )}
      >
        {/* the roles checkboxCheck / checkboxIndeterminate (ui/icon-provider.tsx) draw Lucide heavier so the mark reads at 16 px: 3 on lucide's 24 grid for the check (about 1.75 px at 14 px), 4 for the minus, a short bar that looks thinner than the check at the same weight */}
        <Icon name="checkboxCheck" />
        <Icon name="checkboxIndeterminate" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
}

export { Checkbox }
export type { CheckboxProps }

import * as React from "react"
import { ArrowBigUp, ArrowDown, ArrowLeft, ArrowRight, ArrowRightToLine, ArrowUp, ChevronUp, CommandIcon, CornerDownLeft, Delete, Option, type LucideIcon } from "lucide-react"
import { cn } from "@/lib/utils"

export type KbdTone = "default" | "inverse"

/**
 * Symbol keys (⌘ ⇧ ⌥ ⌃ arrows, enter, backspace, tab) are missing from the mono and Inter fonts, so the browser takes them from a
 * symbol font whose glyphs sit above or below the baseline: crooked in the cap at 100 % zoom. Kbd draws them as Lucide icons, which
 * are centred by construction (the glyph stays for screen readers and text matching).
 */
const KEY_ICONS: Record<string, LucideIcon> = {
  "⌘": CommandIcon,
  "⇧": ArrowBigUp,
  "⌥": Option,
  "⌃": ChevronUp,
  "↑": ArrowUp,
  "↓": ArrowDown,
  "←": ArrowLeft,
  "→": ArrowRight,
  "↵": CornerDownLeft,
  "⏎": CornerDownLeft,
  "⌫": Delete,
  "⇥": ArrowRightToLine,
}
const KEY_PATTERN = new RegExp(`([${Object.keys(KEY_ICONS).join("")}])`)

function SymbolKey({ glyph }: { glyph: string }) {
  const Glyph = KEY_ICONS[glyph]
  return (
    <span data-slot="kbd-symbol" className="inline-flex items-center justify-center">
      <Glyph aria-hidden strokeWidth={2.25} className="size-[1.1em] shrink-0" />
      <span className="sr-only">{glyph}</span>
    </span>
  )
}

function withSymbolIcons(node: React.ReactNode): React.ReactNode {
  if (typeof node === "string" && KEY_PATTERN.test(node)) {
    return node.split(KEY_PATTERN).filter(Boolean).map((part, i) => (part in KEY_ICONS ? <SymbolKey key={i} glyph={part} /> : part))
  }
  if (React.isValidElement<{ children?: React.ReactNode; className?: string }>(node) && node.type === "span" && node.props.children !== undefined) {
    return React.cloneElement(node, { className: cn("inline-flex items-center", node.props.className) }, React.Children.map(node.props.children, withSymbolIcons))
  }
  return node
}

/**
 * A key cap. In a pill field (`rounded-full`) the cap is a pill too (concentric shapes). It is bordered (border-border,
 * muted fill, 11 px text); on a muted or subtle field (its direct parent has `bg-muted`, `bg-subtle` or
 * `bg-bg-subtle`, or an ancestor sets `data-kbd-surface="muted"`, as the library search triggers do) the cap takes the
 * card fill and the control border so the edge stays visible.
 */
function Kbd({ className, tone = "default", children, ...props }: React.ComponentProps<"kbd"> & { tone?: KbdTone }) {
  return (
    <kbd
      data-slot="kbd"
      data-tone={tone}
      className={cn(
        tone === "default"
          ? "inline-flex h-[22px] min-w-[22px] items-center justify-center rounded-sm border border-border bg-muted px-1.5 text-[11px] font-medium text-text-secondary in-[.rounded-full]:rounded-full in-[.rounded-full]:px-2 [.bg-muted>&]:border-border-control [.bg-muted>&]:bg-card [.bg-subtle>&]:border-border-control [.bg-subtle>&]:bg-card [.bg-bg-subtle>&]:border-border-control [.bg-bg-subtle>&]:bg-card in-data-[kbd-surface=muted]:border-border-control in-data-[kbd-surface=muted]:bg-card in-data-[slot=tooltip-content]:border-transparent in-data-[slot=tooltip-content]:bg-bg-tooltip-key in-data-[slot=tooltip-content]:text-neutral-white"
          : "inline-flex h-[18px] min-w-[18px] items-center justify-center rounded-sm bg-bg-tooltip-key px-[5px] text-xs font-semibold text-neutral-white",
        className
      )}
      {...props}
    >
      {React.Children.map(children, withSymbolIcons)}
    </kbd>
  )
}

function KbdGroup({ className, tone, separator, children, ...props }: React.ComponentProps<"div"> & { tone?: KbdTone; separator?: React.ReactNode }) {
  if (tone === undefined && separator === undefined) {
    return (
      <div
        data-slot="kbd-group"
        className={cn("inline-flex items-center gap-1", className)}
        {...props}
      >
        {children}
      </div>
    )
  }

  const arrayChildren = React.Children.toArray(children)

  return (
    <div
      data-slot="kbd-group"
      data-tone={tone}
      className={cn("inline-flex items-center gap-1", className)}
      {...props}
    >
      {arrayChildren.map((child, index) => {
        const keyElement =
          React.isValidElement<{ tone?: KbdTone }>(child) &&
          child.type === Kbd &&
          child.props.tone === undefined
            ? React.cloneElement(child, { tone })
            : child

        const showSeparator =
          separator !== undefined &&
          separator !== null &&
          separator !== false &&
          index < arrayChildren.length - 1

        return (
          <React.Fragment key={React.isValidElement(child) ? child.key : `child-${index}`}>
            {keyElement}
            {showSeparator && (
              <span
                data-slot="kbd-separator"
                className={cn(
                  tone === "inverse" ? "text-xs font-semibold text-neutral-white" : "text-xs text-text-tertiary"
                )}
              >
                {separator}
              </span>
            )}
          </React.Fragment>
        )
      })}
    </div>
  )
}

/**
 * A shortcut legend: one or more key caps and a short label, such as ⌘ K "to open", for the foot of a command menu
 * or a search field. The caps are 22 px tall with the muted fill and 11 px text of a dense legend; the label is
 * tertiary text.
 */
function KbdHint({ keys, label, className }: { keys: string[]; label: string; className?: string }) {
  return (
    <span data-slot="kbd-hint" className={cn("inline-flex items-center gap-1 text-[11px] text-text-tertiary", className)}>
      {keys.map((k, i) => (
        <Kbd key={i} className="h-[22px] min-w-[22px] rounded-sm border border-border bg-muted px-1.5 text-[11px] text-text-secondary">
          {k}
        </Kbd>
      ))}
      <span className="ms-1">{label}</span>
    </span>
  )
}

export { Kbd, KbdGroup, KbdHint }

"use client"

import * as React from "react"

// WAI-ARIA tabs pattern, keyboard part: ←/→ move to the previous/next tab and
// activate it (automatic activation), Home/End jump to the first/last, both
// directions wrap. Works on the DOM, so any tablist whose tabs are buttons
// with role="tab" can use it — the tab's own onClick does the activating.

const TAB = '[role="tab"]'

function ownTabs(list: HTMLElement) {
  return Array.from(list.querySelectorAll<HTMLElement>(TAB)).filter(
    (tab) => tab.closest('[role="tablist"]') === list && !tab.matches(':disabled, [aria-disabled="true"]')
  )
}

/** onKeyDown for an element with role="tablist". */
export function handleTabListKeyDown(event: React.KeyboardEvent<HTMLElement>) {
  if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return
  if (event.altKey || event.ctrlKey || event.metaKey) return
  const list = event.currentTarget
  const current = (event.target as HTMLElement).closest<HTMLElement>(TAB)
  // Keys pressed inside something else in the list (a menu, an input) stay theirs.
  if (!current || current.closest('[role="tablist"]') !== list) return
  const tabs = ownTabs(list)
  if (tabs.length === 0) return
  event.preventDefault()
  const index = Math.max(0, tabs.indexOf(current))
  const last = tabs.length - 1
  const next =
    event.key === "Home" ? 0 : event.key === "End" ? last : event.key === "ArrowRight" ? (index + 1) % tabs.length : (index + last) % tabs.length
  const target = tabs[next]
  // preventScroll + our own nearest scroll: the browser leaves a tab that is only partly visible half hidden, and a
  // focused tab must be seen whole (a scrolling tab bar, a tab list in a narrow panel).
  target.focus({ preventScroll: true })
  target.scrollIntoView?.({ block: "nearest", inline: "nearest" })
  if (target.getAttribute("aria-selected") !== "true") target.click()
}

/**
 * Keeps one tab stop in a tablist whose tabs do not set tabIndex themselves:
 * the selected tab, or the first enabled one when none is selected.
 */
export function useRovingTabStop(ref: React.RefObject<HTMLElement | null>) {
  const sync = React.useCallback(() => {
    const list = ref.current
    if (!list) return
    const tabs = ownTabs(list)
    const stop = tabs.find((tab) => tab.getAttribute("aria-selected") === "true") ?? tabs[0]
    for (const tab of list.querySelectorAll<HTMLElement>(TAB)) {
      if (tab.closest('[role="tablist"]') !== list) continue
      const value = tab === stop ? "0" : "-1"
      if (tab.getAttribute("tabindex") !== value) tab.setAttribute("tabindex", value)
    }
  }, [ref])

  // After every render of the list, and when a tab changes on its own
  // (a TabItem whose parent re-renders without the list).
  React.useLayoutEffect(sync)
  React.useEffect(() => {
    const list = ref.current
    if (!list) return
    const observer = new MutationObserver(sync)
    observer.observe(list, { subtree: true, childList: true, attributes: true, attributeFilter: ["aria-selected", "disabled", "aria-disabled"] })
    return () => observer.disconnect()
  }, [ref, sync])
}
